import base64
import os
import tempfile
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote, urlsplit

RECORDS_DIR = "/var/lib/builder-app/records"


def record_path(record_id):
    encoded = base64.urlsafe_b64encode(record_id.encode("utf-8")).decode("ascii")
    return os.path.join(RECORDS_DIR, encoded)


def store_record(record_id, body):
    fd, temporary = tempfile.mkstemp(dir=RECORDS_DIR, prefix=".record-")
    try:
        with os.fdopen(fd, "wb") as output:
            output.write(body)
            output.flush()
            os.fsync(output.fileno())
        os.replace(temporary, record_path(record_id))
        directory_fd = os.open(RECORDS_DIR, os.O_RDONLY | os.O_DIRECTORY)
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    except BaseException:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise


class RequestHandler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def do_GET(self):
        path = urlsplit(self.path).path
        if path == "/health":
            self.send_response(200)
            self.send_header("Content-Length", "5")
            self.end_headers()
            self.wfile.write(b"ready")
            return

        record_id = self.record_id(path)
        if record_id is None:
            self.send_error(404)
            return
        try:
            with open(record_path(record_id), "rb") as record:
                body = record.read()
        except FileNotFoundError:
            self.send_error(404)
            return
        self.send_response(200)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_PUT(self):
        path = urlsplit(self.path).path
        record_id = self.record_id(path)
        if record_id is None:
            self.send_error(404)
            return
        try:
            length = int(self.headers["Content-Length"])
        except (KeyError, TypeError, ValueError):
            self.send_error(411)
            return
        if length < 0:
            self.send_error(400)
            return
        body = self.rfile.read(length)
        if len(body) != length:
            self.send_error(400)
            return
        store_record(record_id, body)
        self.send_response(204)
        self.send_header("Content-Length", "0")
        self.end_headers()

    @staticmethod
    def record_id(path):
        prefix = "/records/"
        if not path.startswith(prefix):
            return None
        raw_id = path[len(prefix):]
        if not raw_id or "/" in raw_id:
            return None
        try:
            return unquote(raw_id, encoding="utf-8", errors="strict")
        except UnicodeDecodeError:
            return None

    def log_message(self, format_string, *args):
        return


if __name__ == "__main__":
    os.makedirs(RECORDS_DIR, mode=0o755, exist_ok=True)
    server = ThreadingHTTPServer(("0.0.0.0", 8080), RequestHandler)
    server.daemon_threads = True
    server.serve_forever()

